(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.015+t*0.15)*8+Math.cos((y+wy1)*0.012-t*0.1)*6;
  const wy2 = Math.cos((y+wy1)*0.015-t*0.12)*8+Math.sin((x+wx1)*0.013+t*0.18)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.2],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*70,0.05,1.8,1.15],
    [200+Math.sin(t*0.25+1)*100,220+Math.cos(t*0.45+3)*40,0.13,2.4,0.9]
  ];
  let aS=0,iS=0,dS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const dc=1.0/(1.0+d*0.004);
    aS+=Math.sin(d*f-t*sp)*w*dc;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*dc;
    dS+=Math.sin(d*f*1.4-t*sp*0.8+3.0)*w*dc*0.4;
  }
  const act=aS/9,inh=iS/9,dif=dS/9;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.08+sy*0.06-t*0.5)*0.5+Math.sin(sx*0.06-sy*0.09+t*1.5)*0.3)/2.8+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
