  const tex=Math.sin(sx*0.5)*Math.sin(sy*0.5)*Math.sin((sx+sy)*0.3+t*3)*0.06;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+dif*0.4+cell)*2.2);
  const v=reaction*0.5+0.5+tex;
  const pal=[[4,8,38],[10,30,72],[18,65,110],[28,115,130],[55,160,140],[130,195,120],[200,210,80],[235,185,55],[225,130,45],[195,70,50],[150,38,62],[100,22,72],[55,15,58],[22,10,45],[4,8,38]];
  const idx=Math.max(0,Math.min(v*(pal.length-1),pal.length-1.001));
  const i=idx|0,f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.55?1.0+(Math.abs(reaction)-0.55)*0.6:1.0;
  const hShift=Math.sin(ang*2+t*0.3)*4;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+hShift)*lum*edge))|0,
